'use strict';
(function (root) { const data = {"features":{"schema":1,"statuses":{"built":"Built in this release","partial":"Partly built","planned":"Not built yet","na":"Does not apply"},"items":[{"id":"job-experience-document-label","title":"Job document wording","status":"na","note":"This app has no job-related workflows.","group":"voice"},{"id":"language","title":"Language modes","status":"built","article":"languages","note":"English, Hong Kong Cantonese and bilingual modes, saved per computer, in the app and on the website.","group":"voice"},{"id":"funny-emoji","title":"Playfulness sliders and dialog emoji","status":"partial","article":"languages","note":"Separate English and Cantonese playfulness sliders (1 to 5) change the voice of status, empty-state, toast and error copy. The dialog emoji switch is built. Not every string has five voices yet.","group":"voice"},{"id":"personal-vocabulary","title":"Personal vocabulary upload","status":"planned","note":"Not built yet.","group":"voice"},{"id":"vocabulary-drop-apply","title":"Drop a vocabulary file onto the app","status":"planned","note":"Not built yet.","group":"voice"},{"id":"school-mode","title":"School mode","status":"planned","note":"Not built yet. Needs the shared cross-app settings record.","group":"voice"},{"id":"narration","title":"Spoken narrator","status":"planned","note":"Not built yet.","group":"voice"},{"id":"action-sound-effects","title":"Action sounds","status":"built","article":"motion-and-sound","note":"Short synthesized tones when hosting starts, goes live, stops or fails, with a Settings switch and volume. Visual feedback is complete without sound.","group":"voice"},{"id":"scheduled-settings","title":"Scheduled settings","status":"planned","note":"Not built yet.","group":"voice"},{"id":"display-name","title":"Rename the app","status":"built","article":"settings","note":"Change the name shown in the window title and header; one action restores the shipped name. Data folders and package ids never change.","group":"voice"},{"id":"adhd-modes","title":"Focus modes","status":"built","article":"focus-modes","note":"Focus, Low stimulation, Time awareness, One thing at a time and Momentum, each its own switch, all off by default.","group":"voice"},{"id":"dim-sum","title":"Dim sum surprise","status":"partial","article":"dim-sum","note":"A 1 in 10 chance at launch of a non-blocking dim sum note with English and Cantonese names. Pictures are not shown yet because the app makes no network requests from its interface.","group":"voice"},{"id":"dim-sum-photo-source","title":"Dim sum photo source","status":"planned","note":"Not built yet.","group":"voice"},{"id":"material-design","title":"Material Design 3","status":"built","article":"appearance","note":"Material 3 colour roles, shapes, type scale, navigation rail and bottom bar, generated from one seed colour.","group":"look"},{"id":"workflow-navigation","title":"Workflow navigation","status":"built","article":"getting-around","note":"Five destinations in a navigation rail, a bottom bar in narrow windows, and the current step always visible on Host.","group":"look"},{"id":"motion","title":"Motion with a reduced-motion path","status":"built","article":"motion-and-sound","note":"Full, gentle or off, following the system reduced-motion setting. No state is carried by motion alone.","group":"look"},{"id":"live-charts","title":"Live charts","status":"planned","note":"Not built yet.","group":"look"},{"id":"appearance-editor","title":"Per-element appearance editor","status":"planned","note":"Not built yet. Global appearance settings exist.","group":"look"},{"id":"color-picker","title":"Colour picker","status":"partial","article":"appearance","note":"Seed colour by hue wheel, swatches or hex, with the full scheme regenerated live. Colour-space translation is not built.","group":"look"},{"id":"logo-customization","title":"Logo customization","status":"planned","note":"Not built yet.","group":"look"},{"id":"overlay-panels","title":"Overlays and panels","status":"built","article":"getting-around","note":"Notification centre, command palette and confirmations open as layered panels with focus return and Escape.","group":"look"},{"id":"collapse-filters","title":"Collapsible filters and statistics","status":"built","article":"sessions","note":"Session filters and statistics fold away and remember their state.","group":"look"},{"id":"accessibility-sizing","title":"Accessibility and sizing","status":"built","article":"accessibility","note":"Text size from 90 to 150 percent, comfortable or compact density, visible focus, and layouts tested from 420 px wide.","group":"look"},{"id":"functional-ui","title":"Truthful empty states","status":"built","article":"hosting","note":"No link, count or status is shown unless the backend reported it.","group":"look"},{"id":"onboarding-wizard","title":"First-run setup","status":"built","article":"getting-started","note":"Three steps: language and voice, a real Docker and tunnel check, then a short tour. Skippable, resumable, and reopenable from Settings.","group":"nav"},{"id":"tabs","title":"Tabbed navigation","status":"planned","note":"Not built yet.","group":"nav"},{"id":"regex-search","title":"Regex builder on every search","status":"partial","article":"search-and-regex","note":"Every search box has an adjacent regex builder with flags, live token explanation, match count, validation and a time limit. Full RegexBuddy parity is not built.","group":"nav"},{"id":"command-palette","title":"Command palette","status":"built","article":"command-palette","note":"Ctrl+Shift+F opens every destination, action and setting; picking one jumps to it and highlights it. Card or full-window size is remembered.","group":"nav"},{"id":"context-menus","title":"Context menus","status":"partial","article":"getting-around","note":"Right-click or Shift+F10 opens a menu with a filter field for links, paths, sessions and text. Appearance and lock entries are not built.","group":"nav"},{"id":"menu-shortcuts","title":"Shortcuts shown in menus","status":"built","article":"command-palette","note":"Menus and the palette show each working shortcut.","group":"nav"},{"id":"rich-controls","title":"Rich controls","status":"partial","note":"Values such as the public link and local address carry copy and open controls. Not every value does yet.","group":"nav"},{"id":"guided-forms","title":"Guided forms","status":"partial","article":"hosting","note":"The project form explains each field and validates the port as you type.","group":"nav"},{"id":"info-icon-guidance","title":"Info buttons on controls","status":"partial","article":"settings","note":"Every setting has an info button with an explanation. Worked examples and playgrounds are not built.","group":"nav"},{"id":"settings-explanations","title":"Settings that explain themselves","status":"built","article":"settings","note":"Each setting states what it changes and where.","group":"nav"},{"id":"blank-editors","title":"Presets for blank editors","status":"na","note":"The app has no free-form editors.","group":"nav"},{"id":"super-confirmation","title":"Two-key confirmation","status":"built","article":"safety","note":"Stopping a live link, clearing history and resetting settings need two separate keys and a slider, with an emergency exit and Escape.","group":"safety"},{"id":"element-locks","title":"Element locks","status":"planned","note":"Not built yet.","group":"safety"},{"id":"support-tickets","title":"Support ticket recovery","status":"planned","note":"Not built yet.","group":"safety"},{"id":"unlock-ladder","title":"Unlock ladder","status":"planned","note":"Not built yet.","group":"safety"},{"id":"authenticator","title":"Built-in authenticator","status":"planned","note":"Not built yet.","group":"safety"},{"id":"qr-pairing","title":"QR pairing","status":"planned","note":"Not built yet.","group":"safety"},{"id":"honest-monetization","title":"Free, no nagging","status":"built","article":"about","note":"The app is free, has no paid tier, ads or upgrade prompts.","group":"safety"},{"id":"local-history","title":"Local version history","status":"partial","article":"sessions","note":"Every hosting attempt and every settings change is kept locally; a settings revision can be restored as a new revision. Encrypted snapshots are not built.","group":"records"},{"id":"exports","title":"Export everything","status":"partial","article":"sessions","note":"Sessions as JSON, CSV or Markdown; settings, settings history and notifications as JSON. Archives are not built.","group":"records"},{"id":"bulk-actions","title":"Bulk actions","status":"partial","article":"sessions","note":"Select many sessions or notifications to export or remove them.","group":"records"},{"id":"changelog","title":"Changelog viewer","status":"partial","article":"about","note":"Every release with date, changes and commit, with date-range filter and regex search. Exporting the filtered view is not built.","group":"records"},{"id":"offline-docs","title":"Offline guide","status":"built","article":"getting-around","note":"Every article on the website ships inside the app and opens without a network.","group":"records"},{"id":"rendered-provider-text","title":"Rendered provider text","status":"na","note":"The app shows no provider-authored rich text.","group":"records"},{"id":"notifications","title":"Notifications and their centre","status":"built","article":"notifications","note":"Non-blocking toasts, a searchable notification centre with bulk clear, and errors that stay until dismissed.","group":"records"},{"id":"file-converter","title":"File converter","status":"planned","note":"Not built yet.","group":"tools"},{"id":"base64-tools","title":"Base64 tools","status":"planned","note":"Not built yet.","group":"tools"},{"id":"minecraft-server-manager","title":"Minecraft server manager","status":"planned","note":"Not built yet.","group":"tools"},{"id":"minecraft-world-generator","title":"Minecraft world generator","status":"planned","note":"Not built yet.","group":"tools"},{"id":"ollama-suite","title":"Ollama manager","status":"planned","note":"Not built yet.","group":"tools"},{"id":"external-editor","title":"Open in an external editor","status":"planned","note":"Not built yet.","group":"tools"},{"id":"download-handoff","title":"Browser download hand-off","status":"na","note":"There is no browser extension.","group":"tools"},{"id":"forge-publishing","title":"Publishing to a forge","status":"planned","note":"Not built yet.","group":"tools"},{"id":"progress-recovery","title":"Progress and recovery in place","status":"built","article":"hosting","note":"Progress shows on the step that is running and recovery actions appear on the step that failed.","group":"tools"},{"id":"drawesome-drawing","title":"Drawing and annotation","status":"planned","note":"Not built yet.","group":"tools"},{"id":"completeness-parity","title":"Feature inventory","status":"built","article":"features","note":"This list, with the same honest status in the app and on the website.","group":"evidence"},{"id":"front-provenance","title":"Version and build time on the first screen","status":"built","article":"about","note":"Shows the running version and its build time with seconds and time zone, read from the packaged build record, or says it is unavailable.","group":"evidence"},{"id":"product-evidence","title":"Real screenshots","status":"partial","note":"Website screenshots are rendered from the real interface with a scripted backend; they are not captures of live hosting.","group":"evidence"},{"id":"screen-recording","title":"Screen recording","status":"planned","note":"Not built yet.","group":"evidence"},{"id":"design-reference-parity","title":"Design reference parity","status":"partial","note":"The interface follows the checked-in design in design/canvas; a pixel comparison is not automated.","group":"evidence"},{"id":"design-folder","title":"Design files in the repository","status":"built","note":"All design artboards and notes live in design/.","group":"evidence"},{"id":"clipping-matrix","title":"Clipping checks","status":"planned","note":"Not built yet.","group":"evidence"},{"id":"public-screenshot-gallery","title":"Public screenshot gallery","status":"partial","note":"The website has a gallery of interface renders. They are rendered with a scripted backend, not captured from live hosting.","group":"evidence"},{"id":"landing-site","title":"Material website","status":"partial","article":"features","note":"The website carries the feature list, articles, language modes, themes, motion settings, search with regex and the command palette. Not every app feature has a website equivalent.","group":"site"},{"id":"mobile-site","title":"Phone-friendly website","status":"built","note":"Every website section works from 320 px wide.","group":"site"},{"id":"installer-download-button","title":"Download button","status":"built","note":"Points at the latest published release and shows its version and date when the release exists.","group":"site"},{"id":"feature-articles","title":"An article per feature","status":"partial","article":"features","note":"Every built or partly built feature links to an article. Planned features do not have articles yet.","group":"site"},{"id":"vendored-fonts","title":"Bundled fonts","status":"built","note":"Roboto Flex, Roboto Mono and Material Symbols are copied from npm by scripts/vendor-assets.mjs into the app and the website.","group":"site"},{"id":"shared-link-embed","title":"Link preview image","status":"built","note":"The website has Open Graph tags and a preview image.","group":"site"},{"id":"homepage-link","title":"Website linked from the repository","status":"built","note":"The repository About field links to the website, and the README links to it at the top.","group":"site"},{"id":"vocabulary-unlock-boundary","title":"Private wording boundary","status":"na","note":"The app and website are public and have no signed-in surfaces.","group":"site"},{"id":"private-website-app","title":"Packaged website for private repositories","status":"na","note":"This repository is public.","group":"site"},{"id":"status-hub","title":"Status hub","status":"planned","note":"Not built yet.","group":"status"},{"id":"discord-status-bridge","title":"Discord status bridge","status":"na","note":"Part of the status hub app, not this one.","group":"status"},{"id":"panic-webhooks","title":"Panic webhooks","status":"na","note":"Part of the status hub app, not this one.","group":"status"},{"id":"tidbyt-displays","title":"Tidbyt displays","status":"na","note":"Part of the status hub app, not this one.","group":"status"},{"id":"build-entrypoints","title":"build.bat and build-installer.bat","status":"built","note":"Both exist at the repository root.","group":"build"},{"id":"fresh-build-run-command","title":"One build-and-run command","status":"partial","note":"build.bat builds; it does not launch the result yet.","group":"build"},{"id":"dependency-fetcher","title":"One-click dependency fetcher","status":"partial","note":"The tunnel helper downloads and is hash-verified automatically. Docker must still be installed by you.","group":"build"},{"id":"bundled-dependencies","title":"Bundled dependencies","status":"partial","note":"Fonts and icons are bundled; Docker is not.","group":"build"},{"id":"squirrel-installer","title":"Windows installer","status":"planned","note":"The app ships as a portable executable today.","group":"build"},{"id":"self-signing","title":"Code signing","status":"planned","note":"Builds are unsigned.","group":"build"},{"id":"auto-updates","title":"Automatic updates","status":"planned","note":"Not built yet.","group":"build"},{"id":"app-icon","title":"Original icon","status":"planned","note":"Not built yet.","group":"build"},{"id":"release-workflow","title":"A release on every main build","status":"built","note":"Every push to main builds the Windows portable executable and publishes the next tagged release with it.","group":"release"},{"id":"release-timing","title":"Workflow timing in release notes","status":"built","note":"Release notes state how long the build took.","group":"release"},{"id":"release-line-counts","title":"Line counts in release notes","status":"built","note":"Counted by the workflow, never typed by hand.","group":"release"},{"id":"release-dim-sum-photo","title":"Dim sum photos in releases","status":"planned","note":"Not built yet.","group":"release"},{"id":"dim-sum-code-names","title":"Dim sum code names","status":"planned","note":"Not built yet.","group":"release"},{"id":"ci-bootstrap","title":"CI dependency bootstrap","status":"built","note":"Workflows install pinned Node and dependencies with npm ci.","group":"release"},{"id":"runner-selection","title":"Runner selection","status":"partial","note":"Uses GitHub-hosted Windows and Ubuntu runners.","group":"release"},{"id":"encrypted-public-builder","title":"Encrypted builder","status":"na","note":"For private repositories only.","group":"release"},{"id":"tabbed-readme","title":"Tabbed README","status":"partial","note":"The README uses collapsible sections.","group":"repo"},{"id":"human-time-estimate","title":"Human time estimate","status":"planned","note":"Not built yet.","group":"repo"},{"id":"sanitized-instruction-copy","title":"Sanitized instruction copy","status":"partial","note":"AGENTS.md carries the public-safe rules.","group":"repo"},{"id":"agents-md-vocabulary-block","title":"Wording rules in AGENTS.md","status":"built","note":"AGENTS.md states the public wording boundary.","group":"repo"},{"id":"vocabulary-hash-lock","title":"Wording hash lock","status":"planned","note":"Not built yet.","group":"repo"},{"id":"roadmap-checklist","title":"ROADMAP.md checklist","status":"built","note":"ROADMAP.md is generated from this inventory.","group":"repo"},{"id":"feature-docs","title":"A Markdown file per feature","status":"partial","note":"content/articles holds one article per built area, shared by the app and website.","group":"repo"},{"id":"postman-collections","title":"API collections","status":"na","note":"The app exposes no HTTP API.","group":"repo"},{"id":"wiki-website-sync","title":"Wiki and website in sync","status":"partial","note":"The website and the in-app guide are generated from the same articles. There is no wiki.","group":"repo"},{"id":"handoff-record","title":"Handoff record","status":"built","note":"HANDOFF.md is kept current.","group":"repo"},{"id":"closeout-prompt","title":"Closeout prompt","status":"planned","note":"Not built yet.","group":"repo"},{"id":"discussion-records","title":"Discussions as the record","status":"planned","note":"Not built yet.","group":"repo"},{"id":"project-board","title":"Linked project board","status":"planned","note":"Not built yet.","group":"repo"},{"id":"operational-skill","title":"Operational skill file","status":"planned","note":"Not built yet.","group":"repo"},{"id":"readme-prompt-banner","title":"README prompt banner","status":"na","note":"Applies only to the instruction repository.","group":"repo"},{"id":"instruction-single-file-editions","title":"Single-file instruction editions","status":"na","note":"Applies only to the instruction repository.","group":"repo"},{"id":"project-profile","title":"Project memory folders","status":"na","note":"Applies only to the instruction repository.","group":"repo"},{"id":"roblox-model-catalogue","title":"Shared Roblox models","status":"na","note":"Applies only to games.","group":"tools"},{"id":"roblox-visual-realism","title":"Roblox visual realism","status":"na","note":"Applies only to games.","group":"tools"}],"groups":[["voice","Language, voice and personalization"],["look","Appearance and layout"],["nav","Navigation, search and commands"],["safety","Safety, locks and sign-in"],["records","Records, history and messages"],["tools","Built-in tools and hand-off"],["evidence","Completeness and evidence"],["site","Website and shared links"],["status","Status reporting"],["build","Build and install"],["release","Release pipeline"],["repo","Repository records"]]},"articles":[{"id":"about","title":"Version, changelog and price","summary":"The top bar shows the running version and the time it was built, with seconds and the time zone. Both come from the build record packaged with the app. A copy run from source has no build record and says Build time unavailable instead of guessing.","related":["settings","features"],"body":"## Version and build time\n\nThe top bar shows the running version and the time it was built, with seconds and the time zone. Both come from the build record packaged with the app. A copy run from source has no build record and says **Build time unavailable** instead of guessing.\n\n## Changelog\n\n**Settings › About › Changelog** lists every release with its date, changes and commit. Filter by a date range or search with the regex builder.\n\n## Price\n\nThe app is free. There is no paid tier, no advertising and no upgrade prompt."},{"id":"accessibility","title":"Accessibility","summary":"Keyboard first, readable at any size, and announced to screen readers.","related":["focus-modes","motion-and-sound","getting-around"],"body":"Keyboard first, readable at any size, and announced to screen readers.\n\n## Keyboard\n\nEvery control can be reached with **Tab**, has a visible focus ring, and works with **Enter** or **Space**. The command palette (**Ctrl+Shift+F**) reaches every screen, action and setting. **Shift+F10** opens the context menu of the focused item.\n\n## Size and density\n\n- **Text size** scales the whole interface from 90 to 150 percent.\n- **Density** switches between comfortable and compact spacing.\n- Layouts are designed down to 420 pixels wide; nothing is cut off, and long addresses wrap.\n\n## Screen readers\n\nProgress messages, copied links and notifications are announced through a polite live region. Icon-only buttons have names. Errors use an alert role.\n\n## Contrast and motion\n\nColours are generated to keep text at a contrast ratio of at least 4.5 to 1 in both themes. Motion follows your system's reduced-motion setting."},{"id":"appearance","title":"Appearance","summary":"Material Design 3 colours, shapes and type, all generated from one accent colour.","related":["accessibility","motion-and-sound","settings"],"body":"Material Design 3 colours, shapes and type, all generated from one accent colour.\n\n## Theme\n\n**Follow system**, **Light** or **Dark**. The button in the top bar flips between light and dark.\n\n## Accent colour\n\nDrag the hue slider, press a swatch, or type a hex value such as `#3ddbb4`. The app builds its whole colour scheme from it: primary, containers, surfaces and outlines in both light and dark. Text colours are chosen to keep a contrast ratio of at least 4.5 to 1.\n\n## Type and icons\n\nText uses Roboto Flex, addresses and timings use Roboto Mono, and icons come from Material Symbols Rounded. All three are bundled, so the app never loads fonts from the internet.\n\n## What is not built yet\n\nEditing the look of a single element and translating colours between colour spaces are planned."},{"id":"command-palette","title":"Command palette","summary":"Press Ctrl+Shift+F anywhere to find any screen, action, setting or article.","related":["search-and-regex","getting-around"],"body":"Press **Ctrl+Shift+F** anywhere to find any screen, action, setting or article.\n\n## Using it\n\n1. Press **Ctrl+Shift+F**, or the search bar at the top.\n2. Type. Results are grouped as screens, actions, settings and articles.\n3. Use the arrow keys and **Enter**, or click.\n\nChoosing a setting opens its group, scrolls to it, focuses it and highlights it for a moment. Choosing an action runs it, the same way its button would.\n\n## Shortcuts\n\n| Shortcut | What it does |\n| --- | --- |\n| Ctrl+Shift+F | Open the command palette |\n| Ctrl+1 to Ctrl+5 | Host, Sessions, Features, Guide, Settings |\n| Ctrl+Enter | Host app (when a project is chosen) |\n| Ctrl+Shift+C | Copy the live link |\n| Ctrl+. | Stop sharing (opens the confirmation) |\n| Shift+F10 | Context menu for the focused item |\n| Escape | Close the palette, a menu or a dialog |\n\n## Size\n\n**Settings › Accessibility › Command palette size** switches between a centred card and the full window. The choice is remembered.\n\nThe palette has its own regex builder: press **.\\*** inside it."},{"id":"dim-sum","title":"Dim sum surprise","summary":"Each time the app opens there is a 1 in 10 chance of a small dim sum note.","related":["languages","settings"],"body":"Each time the app opens there is a 1 in 10 chance of a small dim sum note.\n\nThe note shows one dish with its English and Cantonese names, waits quietly in the corner, and fades on its own. It never appears during the first-run tour, while hosting is running, or after an error, and it never takes focus.\n\nThe switch in **Settings › Appearance** is a joke: turn it off and it turns itself back on.\n\nPictures of the dishes are planned; the app does not load images from the internet today."},{"id":"features","title":"The feature inventory","summary":"The Features screen and the website list every feature this project aims to carry, with an honest status.","related":["about","getting-around"],"body":"The **Features** screen and the website list every feature this project aims to carry, with an honest status.\n\n| Status | Meaning |\n| --- | --- |\n| Built | Works in this release. |\n| Partly built | Some of it works; the note says what is missing. |\n| Not built yet | Planned, not available. |\n| Does not apply | Not relevant to this app; the note says why. |\n\nThe list in the app and on the website come from the same file, `content/features.json`, so they always agree. Built and partly built items link to their article. Search the list, filter by status, and press a card to open its article."},{"id":"focus-modes","title":"Focus modes","summary":"Five separate switches that make the app easier to follow. All are off until you turn them on.","related":["accessibility","motion-and-sound","settings"],"body":"Five separate switches that make the app easier to follow. All are off until you turn them on.\n\n| Mode | What it changes |\n| --- | --- |\n| Focus | Hides secondary notes, the requirements bar and the footer. |\n| Low stimulation | Softer colours and no motion. Your system's reduced-motion setting still applies on top. |\n| Time awareness | A clock in the top bar, and how long the current step has been running. |\n| One thing at a time | Host shows only the card for the step you are on. |\n| Momentum | A single line under the top bar names the next action. |\n\nThe modes are plain tools. They keep no streaks or scores and make no medical claims."},{"id":"getting-around","title":"Getting around","summary":"Five destinations, one search bar, and a menu on everything you can right-click.","related":["command-palette","notifications","accessibility"],"body":"Five destinations, one search bar, and a menu on everything you can right-click.\n\n## Destinations\n\n- **Host**: choose a project and share it.\n- **Sessions**: every hosting attempt on this computer.\n- **Features**: what the app does, with an honest status for each part.\n- **Guide**: these articles, bundled inside the app so they open offline.\n- **Settings**: appearance, motion, language, focus modes and data.\n\nIn a wide window they sit in the navigation rail on the left. Below 860 pixels they move to a bar at the bottom.\n\n## Context menus\n\nRight-click a link, a path, a session or selected text, or press **Shift+F10** on the focused item. Each menu starts with a filter field: type to narrow it. Menus show the shortcut for each item.\n\n## Panels\n\nThe notification centre, command palette and confirmations open over the screen. **Escape** closes the top one and focus returns to where you were.\n\n## The offline guide\n\nEvery article on the website ships inside the app. Links between articles stay inside the app, and the guide has its own search with the regex builder."},{"id":"getting-started","title":"Getting started","summary":"Install Docker, open the app, pick a project and press Host. The first-run tour checks your computer for you.","related":["hosting","getting-around","languages"],"body":"Install Docker, open the app, pick a project and press Host. The first-run tour checks your computer for you.\n\n## What you need\n\n- **Docker Desktop or Docker Engine**, running. The app checks for it on every launch and from **Check again** on the Host screen.\n- **Docker Compose v2** if you host a Compose project. It ships with Docker Desktop.\n- **The tunnel helper** (`cloudflared`). If it is not installed, the app downloads a pinned official release the first time you host and checks its SHA-256 hash before using it. Nothing is installed system-wide.\n\n## The first-run tour\n\nThe tour has three steps:\n\n1. **Language and voice.** Choose English, Cantonese or bilingual, and how playful the wording should be.\n2. **A real check.** The app asks Docker and the tunnel helper whether they are ready and shows the answers.\n3. **Done.** You land on the Host screen.\n\nYou can skip the tour at any step and run it again from **Settings › About › Run the welcome tour again**.\n\n## Your first link\n\n1. On **Host**, choose **Dockerfile** or **Compose**.\n2. Press the large picker and choose the file.\n3. For Compose, pick the web service. Leave the port empty unless the app cannot detect it.\n4. Press **Host app** and watch each step finish.\n5. When the link card appears, press **Copy link**."},{"id":"hosting","title":"Hosting a project","summary":"Host builds your project, starts it on this computer, checks it, and only then shows a public HTTPS link.","related":["safety","sessions","getting-started"],"body":"Host builds your project, starts it on this computer, checks it, and only then shows a public HTTPS link.\n\n## The steps you see\n\n| Step | What happens |\n| --- | --- |\n| Inspect project | Reads the Dockerfile or Compose file and finds the web port and service. |\n| Prepare tunnel helper | Uses an installed `cloudflared`, or downloads and verifies the pinned release. |\n| Build app | Runs `docker build`, or `docker compose up --build` for Compose. |\n| Start container | Starts an app-owned container bound to `127.0.0.1` on a free port. |\n| Check local health | Requests the app over HTTP until it answers. |\n| Open and verify public link | Creates a Quick Tunnel and requests the public HTTPS address. |\n\nEach step shows its own spinner and timing. If a step fails, the message and the recovery buttons appear on that step, so you never hunt for what went wrong.\n\n## Truthful states\n\nThe link card appears only when the backend reports a verified public address. A link printed in the tunnel's log is not enough. If the app stops answering, the link is cleared at once and the screen says so.\n\n## Stopping\n\n**Stop sharing…** opens a two-key confirmation, because visitors lose access immediately. Stopping removes the app-owned container, image and tunnel. Docker volumes and every container the app did not create are left alone. Closing the app also stops sharing.\n\n## Limits of Quick Tunnels\n\n- Up to 200 requests in flight at once.\n- Server-sent events are not supported.\n- There is no uptime guarantee, and each session gets a new address.\n\nRead the provider's notes at https://developers.cloudflare.com/tunnel/get-started/quick-tunnels/."},{"id":"languages","title":"Languages and voice","summary":"The app and the website speak English, Hong Kong Cantonese, or both side by side.","related":["settings","accessibility","dim-sum"],"body":"The app and the website speak English, Hong Kong Cantonese, or both side by side.\n\n## Language modes\n\n- **English**.\n- **廣東話**: written Hong Kong Cantonese in traditional characters.\n- **Bilingual**: the English label stays first, with the Cantonese label smaller beside or under it. Narrow windows wrap the second label instead of squeezing it.\n\nChange it in **Settings › Language and voice**, or in the first-run tour. The choice is saved on this computer; the website saves its own choice in your browser.\n\n## Playfulness\n\nTwo sliders, one for English and one for Cantonese, go from **1 (serious)** to **5 (playful)**. They change the voice of headings, notifications and empty states. Facts never change: an error still names the same cause and the same fix at every level. Both ship at 5 and reset separately.\n\n## Emoji in dialogs\n\nWhen turned on, confirmations and notifications get one small emoji. Emoji never appear in buttons, labels or the names read by screen readers."},{"id":"motion-and-sound","title":"Motion and sound","summary":"Movement explains what changed. Sound confirms what happened. Both can be turned down or off.","related":["appearance","focus-modes","accessibility"],"body":"Movement explains what changed. Sound confirms what happened. Both can be turned down or off.\n\n## Motion levels\n\n- **Full**: cards rise in, the link card grows into place, the tunnel line flows while sharing, and a failure gives one short shake.\n- **Gentle**: shorter, smaller movements and no looping animation.\n- **Off**: instant changes. This is also used whenever your system asks for reduced motion, whatever you choose here.\n\nMotion never carries meaning on its own. Every state also changes its text, colour or icon.\n\n## Action sounds\n\nShort tones play when hosting starts, when the link goes live, when sharing stops and when hosting fails. They are made by the app itself, so no audio files are loaded. Turn them off or set the volume in **Settings › Motion and sound**. The setting applies at once and is remembered."},{"id":"notifications","title":"Notifications","summary":"Small messages appear in the corner and never block what you are doing.","related":["getting-around","settings","sessions"],"body":"Small messages appear in the corner and never block what you are doing.\n\n## Toasts\n\nSuccess and information messages appear at the bottom and fade after the time you choose in **Settings › Notifications** (3 to 15 seconds). Errors and warnings stay until you dismiss them. Several toasts stack without covering each other.\n\n## The notification centre\n\nPress the bell in the top bar. Every notification is kept there, newest first, with its time. Search it (with the regex builder), select several to dismiss them, export them as JSON, or **Clear all…** with the two-key confirmation. The bell's badge counts unread notifications."},{"id":"safety","title":"Two-key confirmation","summary":"Actions that cannot be undone ask for two separate keys and a slide before they run.","related":["hosting","sessions","settings"],"body":"Actions that cannot be undone ask for two separate keys and a slide before they run.\n\n## Which actions use it\n\n- **Stop sharing** while a link is live.\n- **Clear session history** and **Remove** selected sessions.\n- **Reset all settings** and **Clear all** notifications.\n\n## How it works\n\n1. The confirmation names the exact action and what it affects.\n2. Turn **Key 1** and **Key 2**. Each is its own button, so one stray press is never enough.\n3. The slider unlocks. Drag it all the way to the end, or use the arrow keys, to confirm.\n4. **Emergency exit** or **Escape** closes it at any time, and focus returns to the button you started from.\n\nNothing happens until both keys are on and the slider reaches the end. With motion turned off, the key and slider states still change colour and text, so the confirmation stays clear."},{"id":"search-and-regex","title":"Search and the regex builder","summary":"Every search box in the app and on the website has a regex builder right beside it.","related":["command-palette","sessions","settings"],"body":"Every search box in the app and on the website has a regex builder right beside it.\n\n## Plain search\n\nType to filter. Plain search ignores case and matches any part of the text.\n\n## Regex search\n\nPress **.\\*** beside a search box. The builder opens under it with:\n\n- **Live explanation**: each part of the pattern is listed with what it means, for example `^` as start of text or `(a|b)` as a group with two choices.\n- **Flags**: `i` ignore case, `m` multiline, `s` dot matches newline, `u` Unicode.\n- **Match count** for the current screen.\n- **Validation**: an invalid pattern says why and matches nothing.\n\nEach search keeps its own pattern and flags, so the Sessions search never changes the Settings search.\n\n## Safety limits\n\nPatterns are limited to 300 characters and each searched text to 20,000 characters. Patterns that repeat a repeated group, such as `(a+)+`, are blocked because they can freeze a search.\n\n## What is not built yet\n\nThe builder is not a full RegexBuddy equivalent. Debugging, a library of saved patterns and engine comparisons are planned."},{"id":"sessions","title":"Sessions and history","summary":"Every hosting attempt is saved on this computer so you can look back, search and export.","related":["safety","search-and-regex","settings"],"body":"Every hosting attempt is saved on this computer so you can look back, search and export.\n\n## What a session records\n\nThe file you hosted, the format, the service and port, every step with its time, the outcome (shared, failed, cancelled) and the public address it had. Nothing is uploaded.\n\n## Search and filters\n\n- The search box matches names, paths, addresses and outcomes. Turn on the **.\\*** regex builder for patterns.\n- The outcome chips filter the list, and **Statistics** folds open to show totals, time shared and how many attempts reached live.\n- The filters and the statistics panel remember whether they were open.\n\n## Bulk actions\n\nTick sessions (or **Select all**) to **Export selected** or **Remove…**. Removing uses the two-key confirmation.\n\n## Export formats\n\n- **JSON**: every field, re-importable, UTF-8 with schema version 1.\n- **CSV**: one row per session, UTF-8, CRLF line endings for spreadsheets. Step timings are left out; the file says so in its header row.\n- **Markdown**: a readable table.\n\n## Settings history\n\nEvery settings change is saved as a revision in **Settings › Data and history**. **Restore** brings back an older revision as a new one, so history is never rewritten."},{"id":"settings","title":"Settings","summary":"Everything is saved on this computer, explained in place, searchable, and resettable group by group.","related":["languages","appearance","safety"],"body":"Everything is saved on this computer, explained in place, searchable, and resettable group by group.\n\n## Groups\n\n- **Appearance**: theme and accent colour.\n- **Motion and sound**: motion level, action sounds and volume.\n- **Language and voice**: language mode, playfulness sliders and dialog emoji.\n- **Focus modes**: five separate switches.\n- **Accessibility**: text size, density and command palette size.\n- **Notifications**: how long notifications stay.\n- **Data and history**: settings history with restore, exports, and resets.\n- **About**: version and build time, changelog, the app's name and the welcome tour.\n\nEach setting has an **info** button that explains what it changes. The search at the top finds settings by name or description, with the regex builder beside it.\n\n## Renaming the app\n\n**About › App name** changes the name shown in the window title and the header. **Restore original name** puts it back. Data folders, the package and the update source keep the original name.\n\n## Resetting\n\n**Reset this group** resets one group. **Reset all settings…** resets everything after a two-key confirmation. Old values stay in settings history."}],"changelog":{"schema":1,"repository":"https://github.com/Ding-Ding-Projects/tunnel-app-deployer","entries":[{"version":"0.2","date":"2026-11-06","commit":null,"note":"Released automatically from main; each release's exact version and commit are shown in its build record.","changes":{"Added":["Material Design 3 redesign with a navigation rail, a bottom bar for narrow windows and a live tunnel diagram","Sessions history with search, filters, statistics, bulk actions and JSON, CSV or Markdown export","Features screen with an honest status for every planned feature","Offline guide with every website article","Settings with search, regex builder, settings history and per-group reset","English, Hong Kong Cantonese and bilingual modes with playfulness sliders","Command palette on Ctrl+Shift+F, context menus, notification centre and two-key confirmations","Focus modes, text size, density, accent colour, motion levels and action sounds","Version and build time on the first screen, and a release on every build of main"],"Changed":["The website was rebuilt with the feature inventory, articles, language modes and a command palette"]}},{"version":"0.1.0","date":"2026-11-06","commit":"0d71e2b2c3636e2156cbf87006b7a3d2ba3232fe","note":"Development preview. Not published as a release.","changes":{"Added":["Host a Dockerfile or Compose project and share it through a verified Cloudflare Quick Tunnel","Pinned, hash-verified tunnel helper download","Isolated, app-owned containers with cleanup that keeps volumes","Windows portable build in CI"]}}]}};
  if (typeof module === 'object' && module.exports) module.exports = data; else root.Content = data; })(typeof window === 'undefined' ? globalThis : window);
